function bubblePasses(input) {
  const a = [...input];
  let passes = 0;
  for (let end = a.length - 1; end > 0; end--) {
    passes++;
    let swapped = false;
    for (let i = 0; i < end; i++) {
      if (a[i] > a[i + 1]) {
        [a[i], a[i + 1]] = [a[i + 1], a[i]];
        swapped = true;
      }
    }
    if (!swapped) break;
  }
  return passes;
}

console.log(bubblePasses([1, 2, 3, 5, 4]), bubblePasses([2, 3, 4, 5, 1]));

function insertionComparisons(input) {
  const a = [...input];
  let comparisons = 0;
  for (let i = 1; i < a.length; i++) {
    const item = a[i];
    let j = i - 1;
    while (j >= 0 && (comparisons++, a[j] > item)) {
      a[j + 1] = a[j];
      j--;
    }
    a[j + 1] = item;
  }
  return comparisons;
}

console.log(insertionComparisons([1, 2, 3, 4, 5]), insertionComparisons([5, 4, 3, 2, 1]));

function merge(left, right, compare) {
  const out = [];
  let i = 0;
  let j = 0;
  while (i < left.length && j < right.length) {
    if (compare(right[j], left[i]) < 0) out.push(right[j++]);
    else out.push(left[i++]);
  }
  return out.concat(left.slice(i), right.slice(j));
}

