function selectionSort(items) {
  const a = [...items];
  let swaps = 0;
  for (let i = 0; i < a.length - 1; i++) {
    let min = i;
    for (let j = i + 1; j < a.length; j++) {
      if (a[j] < a[min]) min = j;
    }
    if (min !== i) {
      [a[i], a[min]] = [a[min], a[i]];
      swaps++;
    }
  }
  return { sorted: a, swaps };
}

const a = selectionSort([3, 2, 1, 4, 5]);
console.log(a.sorted.join(" "), "swaps:", a.swaps);
const b = selectionSort([1, 2, 3]);
console.log(b.sorted.join(" "), "swaps:", b.swaps);

