  { id: "r4", stars: 3 }, { id: "r5", stars: 5 }, { id: "r6", stars: 1 },
];

function byStars(list) {
  const buckets = [[], [], [], [], [], []];
  for (const review of list) buckets[review.stars].push(review);
  const out = [];
  for (let stars = 5; stars >= 1; stars--) out.push(...buckets[stars]);
  return out;
}

console.log(byStars(reviews).map((r) => `${r.id}:${r.stars}`).join(" "));

