const statuses = ["delivered", "paid", "shipped", "delivered", "paid", "delivered", "shipped"];

function arrange(a) {
  let lt = 0;
  let i = 0;
  let gt = a.length - 1;
  while (i <= gt) {
    if (a[i] === "paid") {
      [a[lt], a[i]] = [a[i], a[lt]];
      lt++;
      i++;
    } else if (a[i] === "delivered") {
      [a[i], a[gt]] = [a[gt], a[i]];
      gt--;
    } else {
      i++;
    }
  }
  return a;
}

console.log(arrange(statuses).join(" "));
